SELECT id, name, city, age, DENSE_RANK() OVER (PARTITION BY segment ORDER BY age DESC NULLS FIRST) AS age_dense_rank, ROW_NUMBER() OVER (ORDER BY credit_limit DESC, id) AS event_seq, NTILE(3) OVER w_hist AS age_bucket, CUME_DIST() OVER (PARTITION BY city ORDER BY credit_limit NULLS LAST) AS credit_limit_cume_dist FROM customers WHERE credit_limit >= 13500 WINDOW w_hist AS (PARTITION BY segment, country ORDER BY age DESC, id);
